-- Nexmark q15 on flink, BLACKHOLE sink variant. Bidding statistics: COUNT
-- plus two COUNT(DISTINCT) per 10s window. The official query groups by
-- calendar day; a 10s window is the same distinct-set-per-group shape at a
-- size the harness can drain.
-- GENERATED by queries/gen_queries.py from the single cross-engine
-- definition. Edit that file, not this one.
CREATE TABLE bid (
  `auction` BIGINT, `bidder` BIGINT, `price` BIGINT, `channel` STRING, `url` STRING, `datetime` BIGINT,
  ts AS TO_TIMESTAMP_LTZ(`datetime`, 3),
  WATERMARK FOR ts AS ts - INTERVAL '4' SECOND
) WITH (
  'connector' = 'kafka',
  'topic' = 'nx-bid',
  'properties.bootstrap.servers' = 'kafka:29092',
  'properties.group.id' = 'flink-q15bh-bid',
  'scan.startup.mode' = 'earliest-offset',
  'format' = 'json',
  'json.ignore-parse-errors' = 'false'
);
CREATE TABLE sink_q15 (`total` BIGINT, `distinct_bidder` BIGINT, `distinct_auction` BIGINT) WITH ('connector' = 'blackhole');
INSERT INTO sink_q15
SELECT COUNT(*) AS total, COUNT(DISTINCT bidder) AS distinct_bidder, COUNT(DISTINCT auction) AS distinct_auction FROM TABLE(TUMBLE(TABLE bid, DESCRIPTOR(ts), INTERVAL '10' SECOND)) GROUP BY window_start, window_end;
